// One provider, separate operating surfaces. None of these fields carries over automatically.
type Surface = "chatgpt" | "chatgpt-project" | "api" | "codex";

interface SurfaceProfile {
  surface: Surface;
  actor: string;
  credential: string; // a reference, never a secret value
  dataControls: string; // where the governing policy is configured
  toolsAndPermissions: string[];
  operatingOwner: string;
}

const surfaces: SurfaceProfile[] = [
  {
    surface: "chatgpt",
    actor: "named staff member",
    credential: "workspace SSO",
    dataControls: "ChatGPT workspace admin settings",
    toolsAndPermissions: ["admin-approved connectors"],
    operatingOwner: "workspace admin",
  },
  {
    surface: "api",
    actor: "course-feedback-service",
    credential: "env:OPENAI_API_KEY (project-scoped)",
    dataControls: "API project data controls and request settings",
    toolsAndPermissions: ["get_enrollment (read only)"],
    operatingOwner: "platform team",
  },
  {
    surface: "codex",
    actor: "developer in a repository",
    credential: "Codex sign-in",
    dataControls: "sandbox mode and approval policy",
    toolsAndPermissions: ["workspace-write", "network off"],
    operatingOwner: "repository maintainers",
  },
];

interface OutcomeNeeds {
  changesRepository: boolean; // code edits, commands, tests, source-control evidence
  enforcedContract: boolean; // validated input and output, tools, identity, reliability
  organizedContext: boolean; // related files and instructions reused across follow-up work
}

type Surface = "codex" | "api" | "chatgpt-project" | "chatgpt";

function chooseSurface(needs: OutcomeNeeds): Surface {
  if (needs.changesRepository) return "codex";
  if (needs.enforcedContract) return "api";
  if (needs.organizedContext) return "chatgpt-project";
  return "chatgpt"; // supervised exploration, explanation, drafting, analysis
}

// A workflow that crosses surfaces needs an explicit handoff and a control review.
interface Handoff {
  from: Surface;
  to: Surface;
  artifact: string;
  reviewBeforeHandoff: string[];
}

const rubricToGrader: Handoff = {
  from: chooseSurface({ changesRepository: false, enforcedContract: false, organizedContext: true }),
  to: chooseSurface({ changesRepository: false, enforcedContract: true, organizedContext: false }),
  artifact: "rubric drafted in a ChatGPT project, versioned into the grading service",
  reviewBeforeHandoff: ["credential boundary", "data classification", "tool scope", "human approval"],
};

import OpenAI from "openai";

// Stable principles live in code: authenticate, validate, observe.
const client = new OpenAI(); // reads OPENAI_API_KEY from the environment

// Volatile facts live in dated, linked configuration, never in routing rules.
const volatile = {
  model: process.env.OPENAI_MODEL, // verify current ids: https://developers.openai.com/api/docs/models
  verifiedOn: process.env.OPENAI_MODEL_VERIFIED_ON, // ISO date the id was checked
  lifecycleSource: "https://developers.openai.com/api/docs/deprecations",
};
if (!volatile.model || !volatile.verifiedOn) {
  throw new Error("Set OPENAI_MODEL and OPENAI_MODEL_VERIFIED_ON from current official docs");
}

const ageDays = (Date.now() - Date.parse(volatile.verifiedOn)) / 86_400_000;
if (ageDays > 30) {
  console.warn(`Model evidence is ${Math.floor(ageDays)} days old; revalidate before release`);
}

const response = await client.responses.create({ model: volatile.model, input: "Reply with OK." });
if (response.status !== "completed") throw new Error(`Smoke check failed: ${response.status}`);

interface JourneyMapEntry {
  journey: string;
  surface: "chatgpt" | "chatgpt-project" | "api" | "codex";
  inputSources: string[];
  outputConsumer: string;
  tools: string[];
  approvals: string[];
  exclusions: string[]; // what the workflow intentionally cannot do
  operatingOwner: string;
  reviewers: string[];
  evidence: { url: string; verifiedOn: string }[];
  revalidateBy: string;
}

const feedbackDrafting: JourneyMapEntry = {
  journey: "Instructor drafts feedback on a lab submission",
  surface: "api",
  inputSources: ["submission text (untrusted)", "published rubric (trusted)"],
  outputConsumer: "instructor review queue",
  tools: ["get_rubric (read only)"],
  approvals: ["instructor approves before the learner sees feedback"],
  exclusions: ["cannot change grades", "cannot message learners directly"],
  operatingOwner: "curriculum platform team",
  reviewers: ["product", "security", "data", "accessibility", "operations"],
  evidence: [{ url: "https://developers.openai.com/api/docs/quickstart", verifiedOn: "2026-09-11" }],
  revalidateBy: "2026-10-11",
};
